11	export const useMemoHandlers = (options: UseMemoHandlersOptions) => {
12	  const { readonly, openEditor, openPreview } = options;
13	  const { memoRelatedSetting } = useInstance();
14	
15	  const handleMemoContentClick = useCallback(
16	    (e: React.MouseEvent) => {
17	      const targetEl = e.target as HTMLElement;
18	      if (targetEl.tagName === "IMG") {
19	        const linkElement = targetEl.closest("a");
20	        if (linkElement) return; // If image is inside a link, don't show preview
21	        const imgUrl = targetEl.getAttribute("src");
22	        if (imgUrl) openPreview(imgUrl);
23	      }
24	    },
25	    [openPreview],
26	  );
27	
28	  const handleMemoContentDoubleClick = useCallback(
29	    (e: React.MouseEvent) => {
30	      if (readonly) return;
31	      if (memoRelatedSetting.enableDoubleClickEdit) {
32	        e.preventDefault();
33	        openEditor();
34	      }
35	    },
36	    [readonly, openEditor, memoRelatedSetting.enableDoubleClickEdit],
37	  );
38	
39	  return { handleMemoContentClick, handleMemoContentDoubleClick };
40	};
